    (1, 4, 14, 8, 3, 2, '11301', 1, null, 3.54, 0, 0.46, null),
    (1, 4, 14, 9, 3, 3, '6315', 1, null, 29.46, 0, 3.83, null),
    (1, 4, 14, 10, 4, 1, '2111030107', 1, null, 0, 28, null, 3.64),
    (1, 4, 14, 11, 4, 2, '11301', 1, null, 3, 0, 0.39, null),
